/* Testo del Manuale di Gioco (estratto dal PDF) — sezione 'Le regole' */
const RULES_SECTIONS = [
 {
  "t": "Premessa",
  "b": "Benvenuti nel sistema di gioco di ruolo Role Makers System! Qui troverete le regole di base, dettagli sulla creazione dei personaggi e il loro background, su come costruire una scheda, sui duelli, sui combattimenti di massa, sul potenziamento del personaggio e sulla gestione dei level up. Va da sé dire che questo sistema è molto più adatto per i neofiti, non è un sistema complesso (ANZI): nasce proprio dalla scelta di voler creare un sistema di gioco il più aperto (adattabile) e realistico possibile. Sono certo che ne troverete i pregi e i difetti. Il gioco sarà costruito secondo la narrazione del Narratore, il suo mondo e le sue regole, il Role Makers System si adatta ad esso e può essere più o meno forzato a seconda delle differenti ambientazioni della narrazione. Ciò che è richiesto al Narratore e ai giocatori nel primo inserimento all’ambientazione in cui giocherete nel vostro GDR è di lasciar spazio all’immaginazione.\n\nSi tratta di concepire scenari e ambientazioni sotto la guida del vostro Narratore e al tempo stesso di ideare il vostro personaggio e la sua interpretazione di stili di combattimento e, perché no? Anche la magia del mondo. Perciò siate creativi e, soprattutto, DIVERTITEVI."
 },
 {
  "t": "Come giocare",
  "b": "Giocare secondo il Role Makers System richiede l’uso di regole, la loro interpretazione nel mondo e un set di 7 dadi poliedrici che comprendono: 1d4, 1d6, 1d8, 2d10, 1d12 e un d20. Per i neofiti si specifica: i diversi dadi sono indicati dalla lettera d seguita dal numero di lati: d4, d6, d8, d10, d12 e d20. Ad esempio, un d6 è un dado a sei facce (il cubo tipico utilizzato da molti giochi). I dadi percentuali, o d100, funzionano in modo leggermente diverso. Si utilizzano 2 dadi con 10 facce e il risultato sarà dato dal dado compreso tra 0 e 9 (unità) e un dado compreso tra 00 e 90 (decine). Il valore 100 ad esempio è dato da 00 + 0. Il gioco si struttura nel seguente modo:\n\n1) Il Narratore descrive l’ambiente ai giocatori, dove si trovano i loro personaggi e quali sono le loro possibili interazioni o opzioni (quante porte conducono fuori da una stanza, cosa c’è su un tavolo, chi è nel luogo in cui si trovano e così via).\n\n2) I giocatori descrivono ciò che vogliono fare. Questo potrà essere una semplice descrizione da parte del giocatore come “mi alzo, sistemo il cappotto e il mio cappello, controllo che ci sia tutto nelle tasche e dopo aver lasciato i soldi al barista esco a prendere una boccata d’aria”, oppure l’azione sarà descritta ai suoi compagni in forma di dialogo, che potrà essere accolta o contrastata con un dialogo tra personaggi, es: “Prenderemo la porta est”. I personaggi diversi fanno cose diverse: I giocatori, a seconda della situazione, potranno avere turni e parti in singolo o parti di gruppo. La gestione di queste due parti sarà differente. La prima sarà votata alla costruzione di una scena, la seconda al gioco di ruolo diretto tra personaggi o loro azioni, anche se non simultaneamente, es: un personaggio può dover lavorare ad un attrezzo mentre un altro legge e l’altro ancora sta di guardia. Sta al Narratore ascoltare tutti i giocatori e decidere la cadenza delle loro azioni. In certe situazioni, in particolare il combattimento, l’azione è più strutturata e i giocatori (e il Narratore) si alternano nella scelta e nelle azioni risolutive. Il più delle volte, il gioco è fluido e flessibile, adattandosi alle circostanze della narrativa. Spesso l’azione di un’avventura si svolge nell’immaginazione dei giocatori e del Narratore, basandosi sulle sue descrizioni per impostare la propria scena. Non disprezzate la musica come mezzo di narrazione, usare la musica, l’arte o gli effetti sonori registrati per aiutarvi a impostare l’umore della scena è uno strumento che vi deve aiutare a incrementare l’immersione."
 },
 {
  "t": "Personalità e Background",
  "b": "Una volta letta la premessa che vi ha proposto il vostro amico Narratore è tempo di creare la persona, alieno o qualsivoglia bestia che andrete ad interpretare. Il vostro personaggio ha bisogno di un nome. Passate qualche minuto a pensare come appare e come si comporta generalmente. Si dovranno approfondire caratteristiche fisiche, psicologiche e carattere del personaggio. Un’altra cosa fondamentale è la definizione della sua morale, la bussola che guida le sue decisioni e gli ideali. Altre cose fondamentali nella creazione di un personaggio sono i legami (siano essi con la terra d’origine, con familiari o amici o con animali da compagnia oppure oggetti), i difetti del suo carattere, la sua occupazione o predisposizioni e il ruolo del personaggio nel mondo. Il tuo Narratore potrebbe richiedere informazioni ulteriori rispetto a quelle appena suggerite; un background dal vostro Narratore. Una cosa FONDAMENTALE è che non si scrive di personaggi perfetti: il sistema abbandona le strutture rigide e preimpostate per lasciare più libertà ai giocatori e al Narratore. Il personaggio è o non è conforme alla cultura del suo popolo? Di che genere è e che sessualità esprime? Ponetevi delle domande sulla natura del vostro personaggio e rispondete ad esse: è un lavoro “lungo” e richiede il suo sforzo di immaginazione e immersione, ma una volta portato a termine otterrete sicuramente dei risultati soddisfacenti. Esempio — Alida: i dettagli di questo capitolo fanno una grande differenza nell’impostazione del tuo personaggio rispetto agli altri. Alida Etlan è originaria di Pheon, è un’adolescente sfacciata che ha avuto un’infanzia difficile. Una ladra, scappata di casa e che ha praticato insieme a suo padre commerci per le strade del suo borgo. Quando ha cercato di derubare il proprietario della locanda dell’ultima casa in cui ha vissuto, questo la prese sotto la sua ala, dandole un lavoro come barista. Solo quando il regno di Epimno attaccò la città di Pheon, la necessità costrinse Alida alla fuga insieme agli amici che aveva conosciuto durante la sua infanzia. La sua abilità di combattente (il mestolo per lavorare la pasta rimane la sua arma preferita) combinato con la sua storia l’ha resa una ragazza attenta, scaltra e sveglia, insomma un ottimo compagno per un’avventura."
 },
 {
  "t": "Le Regole",
  "b": "L'impostazione della scheda servirà a definire i parametri e le caratteristiche primarie per le vostre azioni. Tratti Caratteristici e Bellezza: per prima cosa, nella scrittura della scheda è bene appuntare quelle che sono le caratteristiche definite durante la stesura del background del personaggio, questa sezione definisce le informazioni generali riguardanti l’aspetto fisico del personaggio come altezza, peso, età, capelli e colore degli occhi. Se non viene definito nel background è possibile tirare un d20, il risultato, più un eventuale bonus razza, definirà la bellezza del personaggio."
 },
 {
  "t": "Caratteristiche primarie",
  "b": "Le caratteristiche primarie del vostro personaggio, che sono i valori che definiscono i tratti, sono 9. Esse sono:\n• HP (Punti Salute)\n• MP (Punti Magia)\n• Forza\n• Mira\n• Velocità\n• Forza Magica/Mentale\n• Destrezza\n• Difesa\n• Difesa Magica/Mentale\nI punti da attribuire a tali tratti sono in tutto 40, suddivisibili nelle differenti caratteristiche. Il minimo valore possibile da attribuire ad una caratteristica è 1, il massimo è a discrezione del giocatore. Esiste inoltre la tipologia di base della propria build, scelta su una terna che ne varia moltiplicatori e metodo di apprendimento delle caratteristiche. Moltiplicatore di tipologia:\n\n**Guerriero:** HP moltiplicato per 10, MP moltiplicato per 2. Si basa principalmente sullo sviluppo di una build fisica che investe tantissimo, già nelle prime battute, sui punti vita del personaggio e la sua resistenza. Il guerriero ha la possibilità di avere fin da subito 2 Tecniche. P.R. iniziali 10.\n\n**Eclettico:** Il moltiplicatore di HP ed MP è interscambiabile, si potrà avere HPx7 e MPx5 o viceversa. Né carne né pesce, spesso usata per creare build miste ed eclettiche. L’Eclettico ha la possibilità di avere fin da subito 1 Tecnica e 1 Abilità magica. P.R. iniziali 8.\n\n**Mago:** HP moltiplicato per 3, MP moltiplicato per 9. La build mago è utile per strutturare un personaggio che investe tantissimo nelle magie, ma inizialmente molto fragile. Il mago ha la possibilità di partire con 2 Abilità magiche. P.R. iniziali 10."
 },
 {
  "t": "Distribuzione delle statistiche secondarie: Q.I. e P.R.",
  "b": "**Q.I.**: (1d4 + 1d6 + 1d10) x 10. Quoziente intellettivo, suddiviso in 4 fasce che definiscono la capacità nell’apprendere le abilità più o meno velocemente, esse hanno standard 0/10, ogni fascia abbassa questo limite. Le fasce dell’abilità nell’apprendimento sono:\nAl di sotto del 100: 0/11;\nTra 100 e 120: 0/10;\nTra 120 e 150: 0/9;\nPer valori superiori a 150: 0/8.\nCi si riserva la possibilità da parte del Narratore di definire un possibile range determinato dal Background. La scelta non è punitiva ma coerente con la definizione del background (un personaggio volutamente pigro nell’apprendimento non potrà mai avere valori alti di Q.I.).\n\n**P.R.**: sono definiti da un valore standard di classe, es. 10 per mago e guerriero e 8 per la classe eclettico. I punti recupero sono quel totale di punti, spendibili in HP/MP, che il personaggio recupera in fase di riposo o meditazione. Il tempo in cui vengono recuperati è SEMPRE a discrezione del Narratore.\n\n**Distribuzione delle statistiche terziarie**: Stile, Fortuna, Carisma.\n\n**Stile**: tiro opzionale, a discrezione del Giocatore che può sbizzarrirsi nel descrivere un’azione altamente spettacolare al posto del Narratore, esso influisce nel guadagnare stima, fiducia, approvazione o anche qualche moneta dai viandanti.\n\n**Fortuna**: tiro a discrezione sia del Narratore che del giocatore, sta però al Narratore scegliere le conseguenze variabili e il successo o fallimento della prova da parte del giocatore nelle giuste proporzioni. A volte viene considerato il tiro di fortuna per stabilire le conseguenze di una determinata azione che necessita di molto “posteriore”.\n\n**Carisma**: tiro a discrezione del Giocatore, impone una qualità recitativa differente in base al risultato della prova, sta al Narratore decidere il fallimento o il successo. Utile per convincere i propri interlocutori e spingerli a compiere azioni che normalmente non farebbero.\n\nPer stimare il bonus/malus iniziale si spendono 5 punti totali nelle tre caratteristiche, es: +2 Car, +4 For, -1 Stile. Si potrà portare uno o più valori ad un valore negativo per incrementare il restante oppure avere un set equilibrato es: +1 Car, +2 For, +2 Stile. I valori non potranno essere portati sotto il -1. Anche questi valori saranno incrementabili. I risultati sono poi assegnabili liberamente dal giocatore.\n\nEsecuzione della prova: il giocatore tira un d20, al risultato del dado aggiunge/toglie bonus/malus per la definizione del risultato.\n\n**Carisma — criterio base**:\nda 1 a 5: per ottenere il successo si necessita di un’interpretazione perfetta;\nda 6 a 11: per ottenere il successo si necessita di un’interpretazione ottima;\nda 12 a 17: per ottenere il successo si necessita di un’interpretazione normale;\nda 18 a 20: per ottenere il successo si necessita di un’interpretazione sotto la norma.\nLa qualità dell’interpretazione è giudicata dal Narratore.\n\n**Stile e Fortuna — criterio base**:\nda 1 a 5: Azione di bassa spettacolarità / Conseguenza molto sfortunata;\nda 6 a 11: Azione di media spettacolarità / Conseguenza un po’ sfortunata;\nda 12 a 17: Azione di grande spettacolarità / Conseguenza fortunata;\nda 18 a 20: Azione di incredibile spettacolarità / Conseguenza molto fortunata.\nLa riuscita della prova è sempre a discrezione del Narratore.\n\n**PP (Punti Potere)**: i PP sono un valore che definisce la quantità di punti utilizzabili con il boost. Fanno parte della seconda scheda (ultimo campo in basso) e definiscono la capacità del personaggio di controllare la sua natura, sia essa fisica o magica. Il valore dei PP è determinato sommando la metà degli HP massimi e la metà degli MP massimi. Es: HPmax = 60; MPmax = 40; PP = (60/2 + 40/2) = 50 PP."
 },
 {
  "t": "Tratti",
  "b": "Ogni personaggio o creatura ha due tipi di tratti: Attributi, Capacità e Conoscenze. Ogni tratto è valutato con un dado dal d4 a un d12, con il d6 come valore medio e il d12 a rappresentare un valore da record, a seconda della sua esperienza. L’uso del dado dipenderà dal valore della caratteristica, es: 1d4 per valori da 1 a 10; 1d6 per valori da 11 a 20; 1d8 per valori da 21 a 30; 1d12 per valori da 31 a 40; 1d12+d8 per valori da 41 a 50.\n\nTiri contrapposti. A volte i tiri sono “contrapposti” con quelli effettuati da un avversario. Se ad esempio due personaggi lottano fra di loro, entrambi effettuano dei tiri contrapposti. Quando questo accade, il personaggio “attivo”, quello che tenta l’azione a scapito di un altro, calcola per primo il suo totale sulla competenza, seguito da chi gli si oppone. Il tiro ottenuto dall’avversario rappresenta il Numero Chiave del tiro che l’avversario deve superare.\n\nProve sulle Capacità e Conoscenze. Se volete che il vostro personaggio faccia qualcosa, il Narratore vi dirà qual è il tratto da usare e voi lancerete il dado corrispondente. Il risultato verrà definito in base ad una scala di valori: da 1 a 7 = Azione con bassa probabilità, conseguenza molto sfortunata, verrà associato 1d4 come dado di svantaggio al tiro sulla caratteristica per il calcolo del successo. da 8 a 12 = Azione di media probabilità, la conseguenza di questo tiro dipenderà da un tiro avversario, qualora non superasse il tiro ricade nelle probabilità sfortunate, ma senza svantaggio. da 12 a 17 = Un tiro compreso tra questi valori è considerato un successo. da 18 a 20 = Azione molto fortunata. Per valori di questo tipo, durante un’azione in combattimento, si ottengono situazioni molto vantaggiose. La riuscita della prova è sempre a discrezione del Narratore. Numero Chiave (NC): il numero da ottenere abitualmente per la maggior parte dei compiti è 12, più o meno i modificatori, ma in alcuni momenti della trama potrà essere definito un valore soglia inferiore o maggiore ad esso a seconda dell’azione che si sta andando a compiere."
 },
 {
  "t": "Esperienza/Inesperienza",
  "b": "se un personaggio non ha alcuna competenza per un’azione che sta tentando, lancia i dadi percentuali (d10), ma sottrae un 20 al totale ottenuto. Perché si possa considerare superata la prova il risultato deve essere pari o superiore a 50%, se non si ha alcuna competenza il risultato di valori molto alti del dado non avranno bonus, nel caso di fallimento, se il valore è al di sotto del 20% si otterranno conseguenze critiche. Alcune abilità non possono mai essere utilizzate da un personaggio inesperto, come eseguire un intervento chirurgico al cervello o lanciare una magia specifica (nel caso della magia si è invitati a sperimentare ma il risultato di un’azione negativa avrà conseguenze critiche). Se invece si ha competenza ed esperienza sul tiro di prova si avranno i bonus e il dado varierà a seconda della caratteristica."
 },
 {
  "t": "Malus psicologici/fisici",
  "b": "I personaggi sono Scossi quando presentano ferite superficiali, lividi, sono frastornati o spaventati. I personaggi possono diventare scossi in seguito a prove di volontà fallite, per la paura e, più comunemente, per danni fisici.\n\nI personaggi scossi possono muoversi solo alla metà del loro passo, all’inizio di ogni azione il giocatore tenta di recuperare la condizione normale effettuando un tiro di Spirito. Un fallimento significa che rimane scosso. Con un successo il giocatore può riprendere il controllo del proprio personaggio avendo a disposizione una sola azione durante quel turno. Se un personaggio già Scosso viene scosso ancora una volta da un attacco riuscito può finire sotto shock o subire una ferita. Ottenere due risultati scosso è quindi una tattica efficace contro avversari con punteggi elevati di Resistenza. Provate a incastrare questi nemici con una prova di volontà capace di scuoterli e poi proseguite con qualcosa di un po’ più letale. Finire fuori dal combattimento non significa sempre che il bersaglio sia proprio morto, ma che sicuramente ha perso contro gli avversari ed è imbelle, se non morente.\n\nFerite sui personaggi. I personaggi possono incassare ferite multiple e ogni incremento sul lancio per i danni infligge loro una ferita. Ogni ferita provoca una penalità di -1 per ogni prova sui tratti. I personaggi che risultano feriti gravemente (es: tre ferite anche non mortali) hanno poco tempo per sistemare almeno una delle ferite prima di finire dissanguati e quindi svenire e/o morire. Un personaggio incosciente deve effettuare immediatamente un tiro su resistenza, applicando i malus e avere un risultato non inferiore a 10 (bonus e malus compresi). Un risultato inferiore porta il personaggio al K.O. o alla morte."
 },
 {
  "t": "Capacità e Conoscenze",
  "b": "Il nucleo di un buon gioco di ruolo è la capacità di creare, personalizzare e far progredire i propri personaggi. Per stabilire le competenze del personaggio e i tratti che lo definiscono maggiormente si dovrà attingere a quanto definito nel background del pg. I giocatori avranno 15 punti spendibili in Conoscenze, **Capacità normali e Capacità combattive**. I valori di un tiro in conoscenze potranno aiutare maggiormente ad esempio nel riconoscere suoni, orme, versi, testi particolari, ecc.\n\nLe capacità invece definiscono le principali abilità del personaggio. Un elenco di abilità standard appare di seguito. Esse sono definite secondo il tipo di arma.\n\n**Conoscenze**:\n• Architettura\n• Bassifondi\n• Caccia\n• Cavalcare\n• Fauna\n• Flora\n• Geografia\n• Gioco d’Azzardo\n• Guidare\n• Meccanica\n• Navigare\n• Orientamento\n• Pesca\n• Politica\n• Sopravvivenza\n• ecc.\n\n**Capacità normali**:\n• Seguire tracce\n• Free running\n• Riparare\n• Scassinare\n• Lanciare\n• Furtività\n• Contrattazione\n• Percezione\n• Ascoltare\n• Intuito olfattivo\n• Persuasione\n• Provocare\n• Intimidire\n• Nuotare\n• Scalare\n• ecc.\n\n**Capacità combattive**:\n• Tattica militare\n• Ascia\n• Spada\n• Lancia\n• Arco\n• Spadone\n• Guardia\n• Guarigione\n• Elusione\n• Resistenza\n• Arte combattiva\n• Spirito\n• ecc."
 },
 {
  "t": "Tecniche",
  "b": "Le tecniche sono abilità fisiche che implicano un effetto supplementare, come può essere “+ N attacchi consecutivi” o “+ N al tiro per l’azione chiamata”. Il loro limite base è 0/10 esse progrediranno con gli utilizzi. Il limite per il LvUp varia in base al Q.I. La tecnica ottiene un LVup con gli utilizzi, una volta raggiunto il suo limite (es: 10/10) sale al livello 2 accumulando un pregio, ed aumentando il suo limite base (es: 0/20, incremento di 10 ogni LvUp). Ad ogni livello la tecnica accumula un pregio scelto dal giocatore e rivisto dal Narratore. Questo è utile se si vuole sviluppare un potere in particolare e si vuole puntare alla sua specializzazione ultima. Ogni 3 Livelli la tecnica accumula sia un pregio che un difetto, a discrezione del Narratore. Le tecniche possono arrivare massimo al livello 10, a livello 10 accumulano 3 pregi.\n\nLa durata dipenderà dalla tipologia di tecnica, se essa può essere passiva o attiva. Ogni 4 livelli si potrà apprendere una nuova tecnica. Curva di Apprendimento/allenamento: In gioco è possibile allenare le capacità e le conoscenze. Ogni ora di allenamento equivale ad due tiri di dado, sia che esso sia di tipo fisico o mentale. Quando il risultato del tiro è 100 (calcolato con i tiri percentuali), il successo vale doppio. Perché si possa apprendere una determinata abilità o conoscenza durante le ore di apprendimento si dovrà ottenere un tiro di dadi pari a 1000. Il limite massimo di apprendimento giornaliero è di 6 ore al giorno, superate le 6 ore si avrà un malus del 15% ad ogni tiro successivo. Un apprendistato di 6h al giorno risulterà profondamente faticoso per il personaggio che potrà avere dei malus fisici o mentali (a seconda dell’addestramento) per alcune giornate a seguire."
 },
 {
  "t": "Magie/Incantesimi",
  "b": "Azioni che sfruttano gli Mp e la Forza Magica. Esse hanno un costo in Mp variabile a seconda del loro livello, viene applicato lo stesso criterio delle tecniche per quanto riguarda la loro durata nel tempo. La forza di tali Abilità avrà un aumento in base al livello e alla forza magica del giocatore. ES: LV 1: 6 Mp; LV 2: 12 MP; LV 3: 18 MP, oltre il livello 4 si ha un incremento di 8 punti Mp al costo dell’azione. Sarà possibile (a seconda dell’avanzamento di trama) far apprendere differenti tecniche o incantesimi con l’allenamento e il tempo necessario, queste verranno poi inserite nella scheda anticipando il LvUp."
 },
 {
  "t": "Boost",
  "b": "Un potenziamento di natura fisica o magica stabilito dal Narratore in funzione del sistema magico presente all'interno del suo mondo, la sua durata base è di 3 Round (turni azione). Il boost può essere di due tipi (fisico o magico), è ciò che definisce il “potere di razza” all’interno del gioco. Esso dipende dai punti capacità PP. l’attivazione del boost richiederà mezzo turno ed un costo di punti potere in base al suo livello di attivazione.\n\nIncrementando di livello sale sia il potenziamento sia la durata. La struttura di gioco del boost si lega principalmente ai valori degli HP massimi ed MP massimi del personaggio, il potere avrà un livello limite di 5 e ad ogni step il Narratore definisce quelle che sono le potenzialità del livello acquisito in base al mondo di gioco. Una cosa fondamentale da apprendere nell’utilizzo del boost è che ogni giocatore, appresi livelli superiori al primo, potrà scegliere quale dei livelli di boost attivare, con relativi costi ed effetti. Va da sé che non sarà sempre necessaria l’attivazione del livello massimo e di spese eccessive per fare azioni che con l’avanzare del gioco possono risultare pressochè banali e ben apprese dai giocatori. Costi di attivazione: il costo di attivazione è sempre fisso e varia in base al livello:\nLV 1 = 8 PP, costo di 5 PP per turno per mantenere attivo l’effetto per 3 Turni.\nLV 2 = 16 PP, costo di 10 PP per turno per mantenere attivo l’effetto per 3 Turni o più.\nLV 3 = 24 PP, costo di 15 PP per turno per mantenere attivo l’effetto per 3 Turni o più.\nLV 4 = 32 PP, costo di 20 PP per turno per mantenere attivo l’effetto per 3 Turni o più.\nLV 5 = 40 PP, costo di 25 PP per turno per mantenere attivo l’effetto per 3 Turni o più.\nAnche i PP sono recuperabili durante il riposo. Il tempo necessario a recuperare i PP dipenderà dal loro utilizzo e dalla quantità effettivamente consumata (A discrezione del Narratore).\n\nLvUp, Limite e Range: Anche il boost, come tutte le altre abilità e tecniche del gioco, incrementa con il suo utilizzo. Il valore del LvUp è definito dai limiti di livello, più si utilizzano PP e più velocemente si arriverà al limite per il LvUp. Ad ogni incremento il boost acquisisce nuove capacità o un miglioramento delle capacità acquisite. Il suo incremento ad esempio può influire nella potenza, nella capacità di controllo e nel range d’azione. I limiti di livello e i range d'azione sono così definiti: LV 1 = 0/100, 5 metri; LV 2 = 0/200, 10 metri; LV 3 = 0/300, 15 metri; LV 4 = 0/400, 30 metri; LV 5 = 0/500, 50 metri. Oltrepassato il livello 5 si otterrà il Lv Top: il livello Top avrà una diminuzione nei costi di attivazione del 10% su tutti e 5 i livelli appresi."
 },
 {
  "t": "Combattimento",
  "b": "Durante la fase di combattimento i personaggi saranno chiamati ad effettuare una serie di azioni utili alla loro sopravvivenza. La fase iniziale del combattimento stabilisce chi avrà modo di agire per primo ed è definita con il nome di iniziativa. Iniziativa: Per aiutare il Narratore a tenere traccia di chi agisce e in quale ordine, si effettua un tiro puro con il d8, esso potrà avere incrementi da particolari abilità spesso apprese da chi costruisce una build votata alla rapidità. L’iniziativa subisce un tiro vantaggio/svantaggio a seconda che si riesca in un attacco furtivo o lo si subisca. Va comunque precisato che un attacco furtivo andato nettamente a buon fine concluderà l’azione con un colpo critico verso il proprio avversario. Tempi d’azione basilari: Sono i tempi di una determinata azione all’interno del Round/Turno. Per Round/Turno, si intende il massimo tempo d’azione di un personaggio in fase di combattimento. Il Narratore può comunque scegliere di aumentare o diminuire il tempo di un Round/ Turno a seconda delle necessità di scena. Per la definizione delle azioni si potrà utilizzare un valore in tempistiche che sommate daranno la durata del round (ovvero 5 Secondi). Ogni azione ha una sua durata ben precisa, esse sono:\n\nSchivata: questa è l’unica azione GRATUITA, è applicabile sia nel round avversario che nel proprio in caso di Contrattacco subito.\n\nContrattacco: T = 0,5 S + Tempo dell’attacco che si intende effettuare. Questa azione detrae il totale di secondi utilizzato al proprio prossimo Round.\n\nColpo Mirato: T = 0,5 S + Tempo dell’attacco che si intende effettuare.\n\nFinta: T = 0,5 S. La finta richiede un tiro percentuale, può essere utilizzata anche da chi non ha “Fintare” nelle capacità combattive, la capacità opposta è Riflessi.\n\nSalto: T = 0,5 S.\nPugno, Daga: T = 1 S.\nCalcio, Spada corta, Pistola: T = 1,5 S.\nSpada media, Accetta, Fionda: T = 2 S.\nSpada lunga, Spada bastarda, Arco, Lancia, Mazza: T = 3 S.\nSpadone, Ascia a due mani, Alabarda, Martello, Balestra/Randello: T = 4 S.\nMagia/Incantesimo/Uso del Potere: T = 2 S."
 },
 {
  "t": "Scontri di massa e sistema militare",
  "b": "Il sistema Militare (RMO) è la zona del regolamento volta a gestire le battaglie tattiche estese: è una cornice narrativa da gestire a discrezione del Narratore, senza strumenti automatizzati dedicati nell'app (che gestisce invece il combattimento individuale). Dentro tale sistema vengono inserite nuove strutture di gioco e nuove capacità percentuali: RMO: Resistenza Massa Operativa (parametro percentuale). SMO: Scheda Massa Operativa (scheda rappresentativa per un gruppo di truppe “MO”). Viene quindi definito il concetto militare di “Massa Operativa”, intesa come una truppa, plotone, o agglomerato in movimento comandabile all’interno di un operazione decisa dal giocatore o dal narratore. Concetti base: metodi di impiego delle forze nel combattimento riferiti in campo pratico e tattico. La dottrina fornisce gli orientamenti per l’impiego delle forze nei casi di grossi scontri o operazioni. La manovra tattica si esprime in termini di risorse (forze, fuoco ed ostacolo), spazio e tempo; essa tende a sfruttare nel miglior modo il terreno, le vulnerabilità dell’avversario e le peculiari capacità delle proprie forze. Tende in primo luogo a distruggere le forze opposte ed in secondo luogo a garantire il possesso di un’area vitale. Si divide in due principi fondamentali:\n\nMassa: poiché i difensori si attestano normalmente in posizioni tatticamente privilegiate (alture, trincee, fortificazioni ecc.), chi attacca deve aver cura di disporre di un’adeguata massa di manovra. Di regola, è sconsigliato attaccare se non si gode di un rapporto di forze favorevole dell’ordine di (almeno) 3 contro 1. Nei casi in cui l’offensiva è obbligatoria, bisogna colpire velocemente anche se non si dispongono delle risorse sufficienti. Sorpresa: l’attaccante sarà tanto più favorito quanto più riuscirà a cogliere impreparato chi si difende, eseguendo l’azione nel modo più rapido e risolutivo possibile. Strategia Militare: l’arte di impiegare nella maniera migliore le risorse disponibili ai fini della guerra; essa è quindi quella branca dell’arte militare che studia i principi generali delle operazioni militari ed imposta e coordina nelle grandi linee il piano generale della guerra, non soltanto sotto gli aspetti militari. La strategia è rivolta ad ottenere risultati definitivi, contrariamente alla tattica, che è più rivolta all’impiego delle risorse sul campo di battaglia per sconfiggere il nemico. Quindi la strategia riguarda il conseguimento ed il mantenimento dell’egemonia, indipendentemente dai risultati dei combattimenti. Gradi militari: Ufficiali Generali: comandanti di grandi unità in grado di operare indipendentemente per lunghi periodi di tempo. Ufficiali Superiori: comandanti di unità in grado di operare autonomamente per brevi periodi di tempo (battaglioni o reggimenti). Ufficiali Inferiori, comandanti di reparti non in grado di operare autonomamente per periodi di tempo significativi. Sottufficiali: con funzioni ausiliarie rispetto agli ufficiali, quali il comando dei reparti di minore livello oppure compiti amministrativi o tecnici che comportano una certa responsabilità. Cavalleria Leggera: Archi, lame corte. Cavalleria di spionaggio o accerchiamento: tipica truppa esplorativa o scambio di informazioni, utilizzano armi corte e leggere. Cavalleria Pesante: Lance, spade, martelli, armi pesanti. Cavalleria da battaglia: combattenti addestrati a combattere a cavallo e non.\n\nFanteria addestrata e ben armata, solitamente sfruttata per proteggere una zona di comando. Fanteria Selezionata: Spade, picche, balestre, armi generiche. Fanteria: composta da elementi non addestrati o non completamente tali, come contadini paesani ecc., solitamente “carne da macello” con in mano armi di fortuna. Unità Lungo Raggio: Archi, catapulte, baliste, magia ecc. Unità composta da arceri: costruttori, maghi ecc. Può essere usata anche come prima linea per limitare il più possibile le truppe nemiche. Unità Versatile: magia, lame corte, spade leggere. Unità composta principalmente da Maghi e Maghicombattenti. Studio ambientale: comprende lo studio del territorio, sono necessari tiri come “Osservare” e capacità basilari come “Geografia”. I tiri di dado possono favorire il giocatore, in quanto il Narratore almeno in parte è tenuto a fornire dei dettagli. Svolgimento iniziale: questa fase si divide in due sottofasi principali che rappresentano le azioni che avvengono poco prima dello scontro e nel suo inizio.\n\nFase 1) Studio Tattico: il/i giocatore/i ha/nno la possibilità di elaborare la prima strategia di battaglia, che andrà ad aumentare o abbassare la RMO (Resistenza Massa Operativa), una statistica percentuale, in base alla qualità di quest’ultima (a discrezione del Narratore). Può conferire un bonus di 10-20-30% in base alla qualità delle scelte del giocatore. Se il giocatore (la sua unità) ottiene un bonus dalla RMO, automaticamente ottiene l’iniziativa e il primo round della battaglia. La RMO è direttamente collegata alla possibilità di infliggere danni alle unità in opposizione: guadagnando un bonus di RMO si ottiene la possibilità di infliggere fino al 30% dei danni aggiuntivi durante la fase di battaglia, intaccando quindi gli HP generali dell’unità nemica in modo più deciso.\n\nFase 2) Primo scontro (definizione del primo Round): durante il primo scontro vengono applicate le direttive base del Generale. Tiro percentuale della RMO (con bonus e malus decisi durante lo studio tattico della Fase 1). Il tiro decreta il primo attaccante e la possibilità di infliggere più danni durante la prima fase (ricordiamoci che è un gioco in cui i dadi contano, quindi non protestate se il tiro iniziale della RMO fallisce nonostante i bonus: è un gioco e come tale va preso). Fase di battaglia, gestita dalla parte di regolamento relativa al combattimento. La fase è in mano al personaggio con il POV, in caso non ci siano POV in corso, è decisa dal Narratore. Guerra aperta: durante la fase di guerra aperta il giocatore/personaggio con POV, ha la facoltà di applicare la propria strategia e mutare quella base per adattarla al momento della battaglia. I tiri fondamentali per questa azione sono 2: Carisma e Fortuna. Il round si svolge in questo modo (per tutte le truppe in guerra aperta, quindi escludendo il Generale fino a quando non scende in campo direttamente): 1) Decisione strategica del giocatore e tiro della RMO. 2) Fase di battaglia. 3) Calcolo dei danni del giocatore (questo calcolo è gratuito). 3b) Calcolo danni Massa Operativa (gratuito ogni 2 Round, PG POV). Il round ovviamente capita a turni a tutti, in base all’ordine di eventi. Per esempio, dopo il round di X ci sarà il round di Y o il round nemico. Il Generale, se NON è direttamente in battaglia ha un round differente dal resto dei personaggi, che viene giocato una volta ogni 2 Round di tutti (avendo uno spazio di spicco durante queste fasi, è giusto rallentare le sue azioni e consentire a tutti di giocare in modo più determinante). Agenti esterni: Fortificazioni: per fortificazione si intende qualsiasi protezione utilizzata per difendersi dalle azioni offensive del nemico. Le fortificazioni sono in generale costruzioni militari progettate per la difesa di avamposti militari o città fortificate. Le funzioni delle fortificazioni sono due:\nEssere di ostacolo all’avanzata dell’attaccante in modo che resti il più a lungo possibile sotto il fuoco dei difensori.\nAssicurare la protezione e mettere al riparo degli attacchi del nemico le truppe incaricate di difendere l’ostacolo. La componente di protezione può essere svolta in due modi: direttamente con l’uso di costruzioni resistenti capaci di arrestare i proiettili nemici e indirettamente con l’uso della distanza e del vantaggio in gettata e più recentemente del camuffamento. A livello di gioco, le Fortificazioni rappresentano un possibile incremento della RMO in fase difensiva. In base alla qualità e al tipo di fortificazioni e a discrezione del Narratore. Una fortificazione crollata, bruciata o danneggiata può anche conferire Malus alla RMO. Armi da Assedio: per semplificare, le possiamo classificare in funzione del loro funzionamento in tre gruppi principali:\nLe macchine nevrobalistiche o a torsione, che utilizzano per il loro funzionamento l’energia liberata dal rapido svolgimento di una matassa, di solito una corda di fibre o di capelli di donna, come la catapulta o onagro, la balista.\nLe macchine a contrappeso, che utilizzano per il loro funzionamento l’energia prodotta dalla caduta del contrappeso come il trabucco e il mangano.\nArtiglieria: utilizzano per il loro funzionamento l’energia prodotta dall’accensione della polvere pirica. A livello di gioco possono fornire un Bonus alla RMO in fase offensiva. Tra le armi da assedio sono comprese le torri, ma il principale Malus di queste armi è il tempo necessario per montarle durante uno scontro. A meno che non arrivino pronte possono essere necessari dei giorni per assemblarle. Restano ancora da definire la rappresentazione degli spostamenti su mappa e le schede delle truppe (Assedio e Assedio Scientifico sono invece già definiti qui sotto — la nota originale li elencava per errore fra le cose mancanti).\n\nAssedio: situazione bellica in cui un esercito circonda e controlla gli accessi ad una località, di solito fortificata, allo scopo di costringere i difensori alla resa o di conquistarla con la forza. Chi mette in atto un assedio si pone lo scopo di isolare chi lo subisce in modo che questi non possa più avere comunicazioni con l’esterno e che non sia in grado di ricevere rifornimenti di cibo o di mezzi. Ciò avviene, solitamente, circondando l’obiettivo col proprio esercito.\n\nAssedio Scientifico: si definisce assedio scientifico l’insieme di tecniche impiegate per assediare una piazzaforte fortificata alla moderna. Dopo l’introduzione dell’artiglieria, la difesa e l’assalto delle città e delle fortificazioni cambiò radicalmente, poiché il tradizionale approccio alle mura era reso impossibile o estremamente costoso in termini di materiali e vite umane dall’efficienza sempre maggiore dei cannoni e delle armi leggere. L’unico modo di superare le nuove fortificazioni (a meno che non si potesse o volesse impiegare l’antichissima e sempre valida tecnica dell’assedio per fame) era quello di portare l’artiglieria in posizione tale da poter praticare una breccia nelle mura, che doveva essere poi presa con un attacco in forze. Per evitare che i cannoni fossero distrutti prima di poter sparare era necessario scavare trincee (accuratamente angolate così da non esporsi al tiro d’infilata dei difensori) e ripari in cui alloggiare artiglierie e serventi al sicuro, per iniziare finalmente il fuoco, che in certi assedi poteva durare giorni. Movimenti:\nFanteria selezionata, Fanteria non selezionata, unità versatili, unità lungo raggio: 4,5 km/h (ovviamente a piedi).\nUnità a cavallo (leggere): 4,5 km in 30 min.\nUnità a cavallo (pesante): 4,5 km in 40 min.\nCorrieri (a piedi): 4,5 km in 40 min.\nCorrieri (a cavallo): 4,5 km in 25 min."
 },
 {
  "t": "Equipaggiamento",
  "b": "Tutto ciò che il vostro personaggio porta con sé, ogni equip ha caratteristiche principali e requisiti per poterla utilizzare, peso, durabilità dell’arma e le caratteristiche di difesa, attacco e principali bonus come perforare, tagliare, stordire, ecc. Oltre all’equipaggiamento da “battaglia” il vostro personaggio potrà avere altri oggetti con sé da riporre nella propria borsa/tasca. Questi ultimi sono suddivisi in Oggetti Normali e Oggetti ad uso rapido. Oggetto Normale: rientrano nella definizione di oggetti normali tutti gli oggetti che non vengono usati in combattimento o che stanno all’interno delle “borse”. ES: una tenda è un oggetto “Normale”. Oggetto Uso Rapido: rientrano nella definizione di oggetti a uso rapido le armi, le munizioni e gli oggetti che non sono portati in “borsa”.\n\nES: una freccia è un oggetto a “Uso Rapido” o un’arma da poter estrarre dalla cintura o faretra. Regola del Peso: il peso trasportabile da un personaggio è uguale a: (forza + Peso)/2. Es: 8 (forza) + 50 (peso) / 2 = 29 Kg. Armi e Scudi principali statistiche: Attacco: valore offensivo dell’arma. Difesa: valore difensivo dell’arma/scudo. Resistenza: valore di resistenza dell’arma (oltre il quale l’arma si rompe). Extra: capacità percentuali come Tagliare, Perforare, Rompere, ecc. per le Armi e Deviare, Bloccare o Respingere per quanto riguarda gli Scudi. Per le armi a distanza verranno definiti dei valori all’interno della sezione riguardante l’equip come: Gittata: (G) massima distanza da cui si può effettuare un colpo utile (Arco). Tempo di ricarica: (Tr) tempo all’interno del Round in cui si ricarica l’arma (Arco). Statistiche base delle armature: Difesa: valore difensivo dell’armatura. Resistenza: valore di resistenza dell’armatura (oltre il quale essa si rompe). Peso: influisce sulla Velocità a discrezione del Narratore. Di seguito si riporta una tabella descrittiva delle tipologie di armi e loro caratteristiche extra legate alla qualità di fattura:"
 },
 // Testo del campo "b" qui sotto aggiornato (checkpoint "Riferimenti tecnici
 // esposti e revisione editoriale"): la vecchia frase "Si potranno spendere
 // 2 apprendimenti dello stesso tipo per livellare..." non è mai stata
 // implementata nel codice (il motore ha sempre trattato ogni assegnazione
 // come autonoma, vedi js/app.js — tecabAssignments/tecabLevelUpRow) ed è
 // stata sostituita col testo che descrive il comportamento reale.
 {
  "t": "Level Up",
  "b": "Durante le fasi di gioco sarà possibile effettuare dei lv up del personaggio, la curva di sviluppo definisce i punti exp da assegnare durante il LvUp. AP: i classici punti esperienza, assegnati secondo una scala di valori crescente, servono alla crescita delle Statistiche Primarie, Secondarie e Terziarie come Punti Recupero, Carisma, Stile e Fortuna. Vengono definiti durante il LvUp. Crescita Statistiche Primarie:\n\nHP: da 0 a 100: 1 AP = 1 HP; da 101 a 250: 2 AP = 1 HP; da 251 a 400: 4 AP = 1 HP. Sopra il 400 incrementano del doppio il loro costo ogni 100 punti.\nMP: da 0 a 100: 1,5 AP = 1 MP; da 101 a 250: 3 AP = 1 MP; da 251 a 400: 6 AP = 1 MP. Incrementano del doppio il loro costo ogni 100 punti.\nAttributi primari (Forza; Forza Magica; Difesa; Difesa Magica; Mira; Destrezza; Velocità): da 1 a 10: 2 EXP = 1 AP; da 10 a 20: 3 EXP = 1 AP; da 21 a 30: 5 EXP = 1 AP; da 31 a 40: 10 EXP = 1 AP; da 41 a 50: 15 EXP = 1 AP. Oltre i 50 incrementano di 5 ogni decina.\nAttributo secondario (Punti Recupero): per quanto riguarda i P.R. il loro incremento seguirà gli stessi step degli attributi primari, ovvero: da 1 a 10: 2 EXP = 1 AP; da 10 a 20: 3 EXP = 1 AP; da 21 a 30: 5 EXP = 1 AP; da 31 a 40: 10 EXP = 1 AP; da 41 a 50: 15 EXP = 1 AP. 50 è il valore massimo raggiungibile. Attributi terziari (Carisma, Fortuna, Stile): Il loro incremento è definito secondo la formula: Val. Lv da raggiungere X 4; Es: Carisma +3 -> 4 = 4 X 4 = 16 AP. L’incremento di queste caratteristiche verrà facilitato anche chiamando l’azione e ottenendo un risultato ottimale del dado. In questo caso si otterrà un più ( + ) da segnare all’interno del campo, quando i + saranno 3 la caratteristica aumenterà di livello. Qualora però l’azione sia risultata negativa durante i tiri verrà segnato un meno ( - ). Nel caso di compresenza di + e - il valore di + da raggiungere sarà 4. Ogni 3 valori - si toglie un valore +. Nel caso di valori negativi il raggiungimento del livello massimo della caratteristica avrà un valore aggiuntivo.\n\nIncremento Lv caratteristiche terziarie: -1 = 16AP; 0 = 8AP; 1 = 4AP; 2 = 8AP; 3 = 12AP; 4 = 16AP; 5 = 20AP; 6 = 24AP; 7 = 28AP; 8 = 32AP; 9 = 36AP; 10 = 40AP; 11 = 44AP; 12 = 48AP; 13 = 52AP; 14 = 56AP; 15 = 60AP; 16 = 64AP; 17 = 68AP; 18 = 72AP; 19 = 76AP; 20 = 80AP. Il valore Max di queste caratteristiche è il 20. Limiti di Livello: I valori sono riferiti al livello attuale, es: da livello 1 al livello 2 si ottengono 30AP.\nLV 2: 0/30AP (+ 2 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 3: 0/30AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 4: 0/35AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze) Guerriero: 2 Tecniche; Eclettico: 1 Tecnica + 1 Abilità; Mago: 2 Abilità.\nLV 5: 0/35AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 6: 0/40AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 7: 0/40AP (+ 1 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 8: 0/45AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 3 perk alle conoscenze) Tutte le classi apprendono 1 Tecnica e una Abilità.\nLV 9: 0/45AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 10: 0/50AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 11: 0/55AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 12: 0/55AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze) Guerriero: 2 Tecniche; Eclettico: 1 Tecnica + 1 Abilità; Mago: 2 Abilità.\nLV 13: 0/60AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 14: 0/70AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 15: 0/70AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 3 perk alle conoscenze).\nLV 16: 0/80AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze) Tutte le classi apprendono 1 Tecnica e una Abilità.\nLV 17: 0/80AP (+ 1 perk alle capacità + 1 perk alle capacità combattive + 1 perk alle conoscenze).\nLV 18: 0/90AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 19: 0/95AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 20: 0/100AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 3 perk alle conoscenze) Guerriero: 2 Tecniche; Eclettico: 1 Tecnica + 1 Abilità; Mago: 2 Abilità.\nLV 21: 0/110AP (+ 2 perk alle capacità + 2 perk alle capacità combattive + 2 perk alle conoscenze).\nLV 22: 0/110AP.\nLV 23: 0/120AP.\nLV 24: 0/120AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 3 perk alle conoscenze) Tutte le classi apprendono 1 Tecnica di livello 2 e 1 Abilità di livello 2.\nLV 25: 0/130AP e +1 livello diretto a un Boost scelto.\nLV 26: 0/130AP.\nLV 27: 0/140AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 3 perk alle conoscenze).\nLV 28: 0/140AP. Guerriero: 2 Tecniche di livello 3; Eclettico: 1 Tecnica di livello 3 + 1 Abilità di livello 3; Mago: 2 Abilità di livello 3.\nLV 29: 0/150AP.\nLV 30: 0/175AP (+ 3 perk alle capacità + 3 perk alle capacità combattive + 3 perk alle conoscenze) e +1 livello diretto a un Boost scelto. Il livello 30 è il livello massimo. N.B. Per quanto riguarda la classe dell’Eclettico si potrà scegliere se apprendere 2 Tecniche, 2 Abilità, oppure una Tecnica e un’Abilità durante i livelli 8, 16 e 24. Ogni perk aggiuntivo può essere speso per apprendere una nuova tecnica, capacità o conoscenza. Qualora il giocatore esplorando il mondo apprenda anche grazie ad un addestramento o studio determinate conoscenze verranno implementate tra quelle già presenti. Quando un Level Up assegna una nuova Tecnica o Abilità, per ciascuna assegnazione il giocatore può scegliere se creare una nuova Tecnica o Abilità del tipo assegnato oppure aumentare di 1 il livello di una Tecnica o Abilità dello stesso tipo già posseduta. Ogni assegnazione viene gestita separatamente dalle altre; una Tecnica non può mai essere convertita in un’Abilità, né viceversa. Non servono più due apprendimenti per ottenere l’aumento di livello: ne basta uno solo. Gli slot iniziali assegnati in fase di creazione del personaggio restano invece obbligatoriamente di livello 1. Dal livello 21 iniziano i Level Up supremi: i tratti crescono solo ai livelli 21 (+2 per categoria), 24, 27 e 30 (+3 per categoria); gli apprendimenti ottenuti al livello 24 nascono al livello 2 e quelli ottenuti al livello 28 nascono al livello 3. Ai livelli 25 e 30 si ottiene un credito da spendere per aumentare direttamente di 1 un Boost confermato, fino al livello massimo del Boost."
 },
 {
  "t": "Inizia qui",
  "b": "Role Makers System è un gioco di ruolo: un gruppo di persone crea personaggi immaginari e li interpreta all'interno di una storia condotta da un Narratore. Il regolamento definisce come costruire un personaggio, come funzionano i tiri di dado, il combattimento e la crescita del personaggio nel tempo, ma lascia ampio spazio all'immaginazione di chi gioca. Questa app digitalizza la scheda del personaggio, i tiri di dado, il combattimento e la gestione della campagna, così il gruppo non deve tenere tutto su carta.\n\nCosa serve per giocare: un account, se vuoi salvare il personaggio nel cloud e ritrovarlo su altri dispositivi (non è obbligatorio: puoi creare e giocare un personaggio anche senza registrarti, resta sul tuo dispositivo finché non colleghi un account); un personaggio, creato con la procedura guidata dell'app; un gruppo, cioè almeno un Narratore e uno o più giocatori riuniti nella stessa storia. Non serve altro materiale esterno: dadi, scheda e calcoli sono gestiti dall'app.\n\nRuoli al tavolo: il Narratore descrive l'ambiente, interpreta i personaggi non giocanti, arbitra le prove non coperte da una regola precisa e gestisce il combattimento dal lato avversario. I giocatori interpretano il proprio personaggio, descrivono cosa vogliono fare ed effettuano i tiri richiesti dal Narratore.\n\nStruttura essenziale di una sessione: il Narratore descrive la scena (dove si trovano i personaggi, cosa vedono, quali opzioni hanno); i giocatori descrivono cosa vogliono fare; quando un'azione ha un esito incerto si effettua un tiro (vedi “Riferimento rapido”); in combattimento si passa a un ordine a turni basato sull'iniziativa; la sessione si chiude quando il gruppo decide di fermarsi e l'app tiene traccia di scene, log e progressi per la sessione successiva.\n\nDa dove continuare: se sei un giocatore, leggi la “Guida rapida del giocatore”; se sei il Narratore del gruppo, leggi la “Guida rapida del Narratore”; se è la prima volta assoluta con tutto il gruppo, leggi “Prima sessione”; per il regolamento completo, sfoglia gli altri capitoli di questo Compendio; per i termini che non conosci, consulta il “Glossario”."
 },
 {
  "t": "Guida rapida del giocatore",
  "b": "Creare il personaggio: tocca “+” nella lista personaggi (o “Crea un personaggio” dal menu di copertina) e segui la procedura guidata in 6 passaggi: Identità e Background (volto/anagrafica, vita, atteggiamento, passato, relazioni: nessun campo qui è obbligatorio, puoi completarli anche più tardi dalla scheda); Classe (determina come cresceranno HP e MP); Statistiche primarie (distribuisci il pool di punti); Tratti (Capacità e Conoscenze); Tecniche e Abilità; Riepilogo (controllo finale). Puoi scegliere la modalità Rapida (solo il minimo indispensabile nella prima scheda narrativa) o Approfondita (tutte e sei le schede narrative): gli step meccanici sono identici e obbligatori in entrambe. Puoi uscire in qualsiasi momento: la bozza resta salvata e la ritrovi per completarla più tardi. Nell'ultimo passaggio tocca “Sei sicuro delle tue scelte?”: l'app chiede conferma spiegando che classe, statistiche primarie, tratti e Tecniche/Abilità iniziali verranno bloccati (si potranno modificare di nuovo solo con un Level Up). Confermando, il personaggio è considerato creato. Ogni modifica si salva da sola sul dispositivo; se hai collegato il personaggio al cloud, si sincronizza automaticamente anche lì poco dopo ogni modifica.\n\nLeggere la scheda: la scheda ha 8 tab. Identità (ritratto, nome, Classe, anagrafica). Background (le 5 sezioni narrative). Fronte Scheda (diagramma statistiche, barre HP/MP/PP, gli strumenti di gioco e combattimento). Tratti (Capacità e Conoscenze). Retro Scheda (Tecniche, Abilità, Boost). Equipaggiamento (armatura, armi/scudi, zaino). Statistiche (primarie/secondarie/terziarie, valori derivati, AP). Livelli (livello attuale, calcolatore costi di crescita). HP, MP, PP e P.R. si trovano tutti nella tab Fronte Scheda, con le rispettive barre e strumenti.\n\nCome funzionano i tiri: tutti gli strumenti di tiro sono nella tab Fronte Scheda. Tiro tratto, per una Capacità/Conoscenza. Tiro statistica, per una caratteristica primaria (il dado usato dipende dal valore della statistica, scelto automaticamente). Tira Resistenza e applica, quando subisci un colpo. Tira danno, per una Tecnica/Abilità. Tira Bloccare, con uno scudo equipaggiato. Attacca, con un'arma dalla lista. Nella tab Statistiche trovi anche il Tiro Q.I. e il tiro percentuale legato alla soglia di K.O. Un tiro che esce al valore massimo o minimo del dado viene evidenziato graficamente (solo enfasi visiva: il successo dipende dal confronto con il Numero Chiave, vedi Riferimento rapido).\n\nCombattimento: per dichiarare un attacco fuori dal tuo turno, tocca “⚔ Attacco!”, che invia una richiesta al Narratore. Quando è il tuo turno da attaccante, tocca “🎲 Tira per colpire e danno”. Quando sei bersaglio di un attacco già risolto, scegli come difenderti: Schiva, Blocca, Salvezza (se applicabile), Contrattacco (se disponibile) o Non mi difendo. Se un effetto ti impedisce Schivata/Blocco (es. sei stordito), l'app te lo segnala e ti fa proseguire con un bottone unico. Dopo il tiro di difesa, l'app mostra quale difesa hai usato, il totale del tiro e se è riuscita o fallita.\n\nLevel Up: si gestisce dalla tab Livelli. Se il tuo personaggio è in una storia con un Narratore, è lui ad assegnare il livello dal suo Account: vedrai il campo bloccato con una nota che te lo spiega. Quando il livello sale, l'app accredita automaticamente gli AP spendibili e sblocca di nuovo statistiche primarie, tratti e tipo di Tecniche/Abilità già confermati, così puoi spendere i nuovi punti. Spendi gli AP con gli stessi controlli usati in creazione; l'etichetta cambia da “Punti rimanenti” ad “AP disponibili” dopo il primo Level Up. Nella tab Livelli trovi anche un calcolatore costi di crescita: indica valore attuale e obiettivo per una statistica e ottieni il costo in AP prima di spendere davvero i punti.\n\nAccount e accesso: puoi giocare senza registrarti (modalità ospite); l'app te lo segnala e ti invita ad accedere/registrarti solo se vuoi salvare i personaggi nel cloud e ritrovarli su un altro dispositivo. Il modulo di accesso/registrazione si trova in copertina. Se hai già una sessione ospite attiva ma vuoi renderla permanente, trovi un modulo dedicato con il bottone “Rendi permanente questo account”. Collegare un personaggio al cloud è facoltativo: finché non attivi “Storia in cloud” sulla scheda, il personaggio resta solo sul tuo dispositivo."
 },
 {
  "t": "Guida rapida del Narratore",
  "b": "Attenzione: l'app ha due meccanismi indipendenti entrambi chiamati “storia”. Il sistema cloud (quello con inviti reali, scene, combattimento, sessioni, notifiche, descritto qui) si crea dal bottone “Crea storia” nella sezione Account, “Le tue storie” (richiede ruolo Narratore/admin sull'account). Il sistema locale (solo su questo dispositivo, protetto da password condivisa, senza account) è un modulo più semplice e separato: il giocatore copia la scheda con “📋 Copia per il Narratore” e il Narratore la incolla con “Importa personaggio”; non è collegato a scene, combattimento o notifiche.\n\nCreare e gestire una campagna: vai in Account, “Le tue storie”, “Crea storia”. Compila nome storia e facoltativamente icona e premessa (titolo + PDF, con l'opzione di pubblicarla subito). La storia compare come card in “Le tue storie”: toccala per aprire la scheda a tutto schermo, che ha 8 tab: Panoramica, Personaggi, PNG, Scene, Combattimento, Riassunto, Premessa, Gestisci.\n\nInvitare i giocatori: non esiste un codice o link di invito da copiare. Il meccanismo è visibilità più richiesta approvata. Nella scheda storia attiva “Rendi visibile nella ricerca dei giocatori”. Il giocatore, dalla propria scheda personaggio (sezione “Storia in cloud”), vede la storia tra le “Storie pubblicate” e invia una richiesta di partecipazione. Tu ricevi un avviso in tempo reale e la richiesta appare nel tab Panoramica e nel tab Gestisci, dove approvi o rifiuti. Dopo l'approvazione il personaggio è collegato alla tua storia.\n\nGestire le scene (tab Scene): crea una scena con titolo, luogo (facoltativo), testo pubblico (facoltativo) e note private (facoltative) con il bottone “+ Prepara scena”. Ogni scena ha uno stato, Bozza, Pronta o Giocata, cambiabile da un menu a tendina sulla riga. Riordina le scene con le frecce, modificale o eliminale. Il tab Panoramica mostra quante scene sono “Pronte”.\n\nPreparare il combattimento (tab Combattimento): tocca “⚔ Avvia combattimento”. Nella sezione “Metti in scena”, spunta i personaggi (giocatori o PNG) che partecipano; i PNG si generano prima nel tab PNG (“🎲 Genera PNG”), poi si mettono in scena come qualunque altro personaggio. Ogni partecipante messo in scena va posizionato sulla mappa: finché qualcuno non ha una posizione, il bottone “Rivela iniziativa” resta disabilitato. Una volta posizionati tutti, rivela l'iniziativa e gestisci i turni dal tabellone.\n\nMappe e token: carica le immagini di sfondo mappa dalla libreria “🖼 Ambientazioni” (tab Gestisci). Il tabellone è a griglia esagonale; sposti i token trascinandoli o cliccando una cella. Puoi creare più livelli/mappe per lo stesso combattimento e impostare un focus di mappa condiviso visibile anche ai giocatori. Non esiste un tipo “creatura” separato: ogni nemico è un personaggio PNG generato col Randomizzatore.\n\nRicompense e avanzamento: gli AP sono la valuta di crescita del personaggio. Assegna livello (tab Personaggi) fa salire di livello il personaggio e accredita automaticamente gli AP spendibili. Concedi punti tratto assegna punti su una Capacità/Conoscenza specifica. Concedi un apprendimento assegna una Tecnica o un'Abilità. Dalla “🎒 Borsa del Narratore” (tab PNG) puoi raccogliere oggetti e assegnarli a un giocatore.\n\nAltri strumenti riservati al Narratore: registro attacchi (storico dei colpi risolti); diario/recap di sessione (tab Riassunto, con opzione privata o pubblica al gruppo); avvio/chiusura sessione (quando avvii la sessione, i giocatori ricevono una notifica e alcune funzioni della loro scheda si sbloccano); gestione delle richieste in attesa (ingressi da approvare, tratti proposti dai giocatori); eliminazione della storia quando la campagna è conclusa.\n\nPrima sessione, cosa vedi in Panoramica: sessione di gioco (stato attuale e riferimento sessione); ultimo recap; richieste dei giocatori; scene pronte; il tavolo a colpo d'occhio (quanti personaggi giocatore, PNG e oggetti nella Borsa hai in campagna). Non esiste ancora un concetto di “obiettivi di campagna” strutturati."
 },
 {
  "t": "Prima sessione",
  "b": "Pensata per un gruppo che gioca insieme per la prima volta con l'app.\n\nPreparazione: il Narratore crea la storia e attiva “Rendi visibile nella ricerca dei giocatori” così il gruppo la trova. Ogni giocatore crea il proprio personaggio con la procedura guidata, anche solo in modalità Rapida, per arrivare al tavolo con qualcosa di giocabile. Facoltativo ma consigliato: il Narratore carica una premessa per dare al gruppo il contesto della storia.\n\nCreazione del gruppo: ogni giocatore cerca la storia tra quelle pubblicate e invia una richiesta di partecipazione; il Narratore approva le richieste; una volta approvati tutti, il gruppo è formato.\n\nControlli iniziali del Narratore: aprendo la scheda storia, il tab Panoramica dà un riepilogo rapido (sessione chiusa o avviata, ultimo recap, richieste dei giocatori, scene pronte, quanti personaggi si sono uniti). Quando sei pronto, avvia la sessione dal tab Gestisci: ogni giocatore riceve una notifica e alcune funzioni della sua scheda (Riposo, uso di Tecniche/Abilità) si sbloccano.\n\nSequenza guidata della prima scena: prepara almeno una scena in anticipo e portala allo stato “Pronta”; descrivi ai giocatori l'ambiente e le loro opzioni; ogni giocatore descrive cosa vuole fare; quando un'azione ha un esito incerto, richiedi un tiro; segna la scena come “Giocata” quando è conclusa.\n\nEsempio di tiro: un giocatore vuole scassinare una serratura e serve una prova di Capacità. Il giocatore usa lo strumento “Tiro tratto”, seleziona la Capacità pertinente e tocca “Tira”: l'app mostra il totale e il dettaglio del tiro. Il Narratore confronta il risultato con il Numero Chiave che aveva in mente per quella prova (di norma 12, salvo diversa scelta per la scena).\n\nEsempio di combattimento: dal tab Combattimento tocca “Avvia combattimento”; metti in scena i personaggi coinvolti; posiziona tutti sulla mappa; rivela l'iniziativa; ogni giocatore, al proprio turno, dichiara l'azione e tira per colpire, e chi è bersaglio sceglie come difendersi; il combattimento prosegue a turni fino alla conclusione narrativa decisa dal Narratore.\n\nConclusione della sessione: chiudi la sessione dal tab Gestisci quando il gruppo si ferma; pubblica un recap (tab Riassunto), privato o condiviso subito col gruppo. La sessione successiva riparte dal tab Panoramica, che mostra il recap e le eventuali scene ancora da preparare."
 },
 {
  "t": "Glossario",
  "b": "AP (Punti Avanzamento): i punti spesi al Level Up per far crescere le caratteristiche del personaggio; il loro costo cresce con il livello da raggiungere.\n\nAttacco: il valore offensivo di un'arma; nella scheda distingue l'arma equipaggiata da quella nello zaino.\n\nBoost: un potenziamento attivabile a consumo di PP, con 5 livelli di intensità crescente (costo, mantenimento per turno, raggio d'azione). Oltre il livello 5 si ottiene il “Lv Top”, che riduce il costo di attivazione.\n\nCapacità (Normali e Combattive): una delle categorie di tratto del personaggio, insieme a Conoscenze; definiscono le abilità pratiche e belliche del personaggio.\n\nCombattimento: la fase di gioco a turni in cui i personaggi attaccano, si difendono (Schivata/Blocco) e subiscono danni.\n\nConoscenze: l'altra categoria di tratto insieme alle Capacità: le competenze “di sapere” del personaggio.\n\nDifesa: due significati distinti che si sommano nella stessa formula: una caratteristica primaria del personaggio, e il valore difensivo di un'arma/scudo/armatura.\n\nDurabilità: quanto un'arma o un'armatura può ancora incassare colpi prima di rompersi. Le armi la perdono quando attaccano; le armature e gli scudi la perdono quando assorbono danni. A durabilità 0 il pezzo non è più utilizzabile finché non viene riparato.\n\nHP (Punti Vita): i punti vita del personaggio; a 0 il personaggio è K.O.\n\nIncantesimi: sinonimo di Magie; nell'app la categoria corrispondente si chiama “Abilità”.\n\nLevel Up: l'avanzamento di livello del personaggio: si spendono AP per aumentare caratteristiche primarie, secondarie e terziarie, e si ottengono nuovi “perk” alle Capacità/Conoscenze.\n\nMagie: la categoria di poteri magici del personaggio, con un costo in MP che cresce col livello dell'incantesimo.\n\nMP (Punti Magia): la risorsa spesa per lanciare Magie/Incantesimi.\n\nNarratore: chi guida la partita, descrive scene, interpreta i personaggi non giocanti, arbitra i tiri e gestisce il combattimento dal lato avversario.\n\nP.R. (Punti Recupero): il totale di punti, definito dalla classe, che il personaggio recupera e può spendere in HP/MP durante il riposo.\n\nPP: la risorsa che alimenta i Boost, calcolata come metà degli HP massimi più metà degli MP massimi.\n\nQ.I. (Quoziente Intellettivo): la statistica secondaria che determina quanto velocemente un personaggio impara le Tecniche.\n\nResistenza: il tratto di combattimento usato nei tiri di salvezza contro i colpi critici.\n\nRMO (Resistenza Massa Operativa): la statistica alla base del sistema di scontri di massa/militari; oggi descritto solo dal regolamento, senza ancora strumenti dedicati nell'app.\n\nSchivata: l'azione difensiva gratuita in cui il personaggio evita il colpo tirando Elusione; alternativa al Blocco.\n\nStatistiche primarie: le statistiche di base del personaggio (Forza, Forza Magica, Difesa Magica, Difesa, Mira, Destrezza, Velocità, HP, MP), distribuite con un pool di punti in fase di creazione.\n\nTecniche: la categoria di abilità fisiche/marziali del personaggio, che salgono di livello con l'uso fino a un limite legato al Q.I.\n\nAcronimi: AP = Punti Avanzamento; HP = Punti Vita; MP = Punti Magia; P.R. = Punti Recupero; PP = risorsa dei Boost; Q.I. = Quoziente Intellettivo; RMO = Resistenza Massa Operativa."
 },
 {
  "t": "FAQ",
  "b": "Account e accesso.\nDevo registrarmi per giocare? No: puoi giocare come ospite. Senza account, però, il personaggio non è salvato nel cloud e non lo ritrovi su un altro dispositivo.\nCome recupero la password? Dalla schermata di accesso, link “Password dimenticata?”.\nPosso cambiare il nickname visibile agli altri? Sì, dalla sezione Account.\n\nPersonaggi.\nIl personaggio si salva da solo? Sì: le modifiche alla scheda vengono sincronizzate con il cloud automaticamente quando sei collegato a un account. Posso avere più personaggi? Sì, l'app gestisce un archivio dei personaggi creati.\n\nCampagne.\nCome faccio a unirmi a una campagna di un Narratore? Non esiste un codice o link di invito: se il Narratore ha reso la sua storia visibile nella ricerca, la trovi dalla tua scheda personaggio e invii una richiesta di partecipazione, che il Narratore approva.\nChi può vedere la mia scheda in una campagna? Dipende dai permessi impostati per la campagna, con possibilità di uscire dalla storia in qualsiasi momento.\n\nTiri.\nChi decide quale dado uso per una prova? Il dado dipende dal valore della caratteristica usata; l'app lo sceglie automaticamente nel tool “Tiro statistica”.\n\nCombattimento.\nCome mi difendo da un attacco? Scegli Schivata (gratuita, tiro Elusione) o Blocco (se hai uno scudo, tiro Guardia). Se non ti difendi, o se l'attacco è a sorpresa, il colpo è automaticamente critico.\n\nDurabilità.\nPerché la mia arma non funziona più? Ogni arma/armatura/scudo ha una Durabilità che si consuma quando l'arma attacca o l'armatura/scudo assorbe un colpo. A Durabilità 0 il pezzo risulta rotto e non è più utilizzabile finché non viene riparato.\n\nSalvataggio e sincronizzazione.\nCosa succede se gioco offline? Le modifiche restano segnate come da sincronizzare e vengono inviate al cloud non appena la connessione torna disponibile.\n\nContenuti personalizzati.\nPosso creare i miei contenuti di campagna? Sì: dalla sezione Contenuti personalizzati puoi creare, mettere in stato di bozza o pubblicare contenuti collegati a una tua campagna, e duplicarli per riutilizzarli.\n\nPrivacy, export e cancellazione.\nPosso scaricare tutti i miei dati? Sì: dalla sezione Account, bottone “Esporta i miei dati”, che restituisce solo i dati dell'utente collegato. Posso cancellare il mio account? Sì: bottone “Elimina account” nella sezione Account; la cancellazione è reale (rimozione dai sistemi di autenticazione e revoca delle sessioni), non solo una disattivazione. Dove sono i termini di servizio e l'informativa privacy? Attualmente l'app mostra un avviso onesto: informativa privacy e termini di servizio in preparazione.\n\nAssistenza.\nCome contatto l'assistenza? Scrivendo all'indirizzo email indicato nella sezione Assistenza dell'Account."
 },
 {
  "t": "Riferimento rapido",
  "b": "Sequenza del turno (combattimento): iniziativa, tiro di 1d8 + Velocità del personaggio, determina l'ordine di azione. Ogni personaggio agisce nel proprio Round, nei limiti del tempo d'azione disponibile (di norma 5 secondi per Round). Schivata è l'unica azione gratuita e può essere usata anche nel Round avversario (incluso come Contrattacco).\n\nAzioni disponibili e loro tempo: Schivata, gratuita. Contrattacco, 0,5 S + tempo dell'attacco effettuato. Colpo Mirato, 0,5 S + tempo dell'attacco effettuato. Finta (tiro percentuale, si oppone con Riflessi), 0,5 S. Salto, 0,5 S. Pugno, Daga, 1 S. Calcio, Spada corta, Pistola, 1,5 S. Spada media, Accetta, Fionda, 2 S. Magia/Incantesimo/Uso del Potere, 2 S. Spada lunga, Spada bastarda, Arco, Lancia, Mazza, 3 S. Spadone, Ascia a due mani, Alabarda, Martello, Balestra/Randello, 4 S.\n\nTiri principali: Iniziativa, 1d8 + Velocità. Statistica primaria (Prove), dado in base al valore (1d4 fino a 10, 1d6 fino a 20, 1d8 fino a 30, 1d12 fino a 40, 1d12+d8 oltre) più il valore. Schivata, 1d20 + Elusione. Blocco, 1d20 + Guardia (con scudo). Controllo critico (dopo una difesa fallita), 1d20 + Resistenza. Tiro di stato (subire un effetto), 1d100 + bonus.\n\nDanni e difese: un attacco può essere affrontato con Schivata, Blocco o nessuna difesa. Scegliere nessuna difesa (o subire un attacco a sorpresa, che impedisce Schivata/Blocco) porta a un colpo critico automatico (salvo danno di tipo misto). Se invece la difesa viene tentata e fallisce, si tira un controllo critico (1d20 + Resistenza) contro il tiro d'attacco. Durabilità dell'equipaggiamento: le armi perdono durabilità quando attaccano; le armature/scudi la perdono quando assorbono un colpo. A durabilità 0 il pezzo è rotto e non più utilizzabile.\n\nStati applicabili in combattimento, con durata in turni: Bruciare 3, Elettrificare 1, Congelare 5, Avvelenare 5, Sanguinare 3, Accecare 2, Rallentare 3, Immobilizzare 2, Stordire 1, Confondere 2, Silenziare 2, Corrodere 3. Applicati con una Tecnica/Abilità a danno dedicata, risolti con un tiro contrapposto percentuale.\n\nAvanzamento (Level Up): il costo in AP per salire di livello cresce lungo la progressione (LV2 = 30 AP, fino a LV30 = 175 AP). Le statistiche terziarie (Carisma, Fortuna, Stile) costano “livello da raggiungere × 4” AP. Le Tecniche salgono di livello con l'uso, fino a un limite che dipende dal Q.I. del personaggio."
 },
 {
  "t": "Esempi completi",
  "b": "Creazione del personaggio (esempio di calcolo): un personaggio Guerriero ha HP primario 20 e MP primario 5 (valori scelti solo per l'esempio, entro il pool di 40 punti su 8 caratteristiche primarie). Il moltiplicatore di classe Guerriero è HPx10/MPx2: HPmax = 20 × 10 = 200; MPmax = 5 × 2 = 10; PP = HPmax/2 + MPmax/2 = 100 + 5 = 105.\n\nTiro semplice (Prova su una caratteristica): il dado da usare dipende dal valore della caratteristica: 1d4 fino a 10, 1d6 fino a 20, 1d8 fino a 30, 1d12 fino a 40, 1d12+d8 oltre. Un personaggio con Forza 15 userà 1d6: il risultato del dado si somma al valore stesso della caratteristica. Se il dado desse un 4 (valore illustrativo), il totale della prova sarebbe 15 + 4 = 19.\n\nUso di un Boost: un personaggio attiva un Boost di livello 3, costo di attivazione 24 PP, mantenimento 15 PP a turno finché resta attivo, raggio d'azione 15 metri. Se il personaggio ha Lv Top (oltre il livello 5 appreso), il costo di attivazione scende del 10%: 24 × 0,9 = 21,6, arrotondato per difetto a 21 PP.\n\nAttacco e difesa: un attaccante dichiara un attacco. Il bersaglio può scegliere Schivata (tira 1d20 + Elusione), Blocco (tira 1d20 + Guardia, se ha uno scudo) o nessuna difesa. Se il bersaglio non si difende, o subisce un attacco a sorpresa, l'attacco è automaticamente critico (salvo danno di tipo misto). Se la difesa viene tentata e fallisce, si tira un controllo critico (1d20 + Resistenza) contro il tiro d'attacco: se il controllo non lo supera, il colpo è critico.\n\nApplicazione di uno status: una Tecnica/Abilità a danno con effetto “Bruciare” colpisce un bersaglio: si tira un contrapposto percentuale (1d100) tra attaccante e difensore. Se l'attaccante prevale, il bersaglio subisce lo status Bruciare per 3 turni.\n\nPerdita di durabilità: un'armatura con durabilità corrente 50 subisce un colpo che ne riduce il valore. Se la perdita calcolata fosse 12 punti (valore illustrativo: la formula reale dipende dal danno inflitto e dal rapporto di Resistenza tra attaccante e bersaglio), la durabilità corrente scenderebbe a 38/50. Quando la durabilità corrente arriva a 0, il pezzo risulta rotto e non più utilizzabile finché non viene riparato.\n\nLevel Up: un personaggio passa dal livello 1 al livello 2: costa 30 AP e concede +2 perk alle Capacità, +1 perk alle Capacità combattive, +1 perk alle Conoscenze. Nello stesso Level Up, decide di alzare Carisma da 3 a un obiettivo di livello 4: costo 4 (livello da raggiungere) × 4 = 16 AP."
 }
];

/* Indice per capitoli ("raccoglitori"): raggruppa le sezioni di
   RULES_SECTIONS (il testo resta lì, non duplicato) in 10 capitoli
   navigabili invece di un unico elenco piatto lunghissimo. Gli indici
   sono posizioni dentro RULES_SECTIONS. */
const RULES_CHAPTERS = [
  { t: 'Premessa', sections: [0] },
  { t: 'Come giocare', sections: [1, 2] },
  { t: 'Le regole', sections: [3, 4, 5] },
  { t: 'Tratti', sections: [6, 9, 7, 8] },
  { t: 'Tecniche e magia', sections: [10, 11, 12] },
  { t: 'Equipaggiamento', sections: [15] },
  { t: 'Combattimento', sections: [13, 14] },
  { t: 'Level Up', sections: [16] },
  { t: 'Guide', sections: [17, 18, 19, 20, 21, 22, 24] },
  { t: 'Riferimento rapido', sections: [23] }
];

/* Copertina illustrata di un intero capitolo (chiave = t in RULES_CHAPTERS):
   compare una sola volta in cima al pop-up, prima di tutte le sue
   sotto-sezioni. Le immagini arrivano un gruppo alla volta via upload,
   quindi non tutti i capitoli ne hanno ancora una. */
const RULES_CHAPTER_COVERS = {
  'Premessa': 'img/rules/premessa.png',
  'Come giocare': 'img/rules/creare-un-personaggio.png',
  'Le regole': 'img/rules/le-regole.png',
  'Tratti': 'img/rules/tratti-conoscenze-capacita.png',
  'Tecniche e magia': 'img/rules/tecniche-magie.png',
  'Equipaggiamento': 'img/rules/equipaggiamento.png',
  'Combattimento': 'img/rules/combattimento-scontri.png',
  'Level Up': 'img/rules/level-up.png'
};

/* Copertina illustrata di una singola sotto-sezione (chiave = s.t in
   RULES_SECTIONS): usata per gli argomenti che hanno una propria immagine
   dedicata oltre (o al posto di) quella dell'intero capitolo — es. "Boost"
   dentro "Tecniche e magia". Sezioni senza voce qui restano testo puro. */
const RULES_SECTION_COVERS = {
  'Come giocare': 'img/rules/come-giocare.png',
  'Personalità e Background': 'img/rules/personalita-background.png',
  'Caratteristiche primarie': 'img/rules/caratteristiche-primarie.png',
  'Boost': 'img/rules/boost.png'
};

/* Paragrafo introduttivo di un intero capitolo (chiave = t in
   RULES_CHAPTERS): compare subito dopo la copertina, prima di TUTTE le
   sotto-sezioni — es. il capoverso "Il tuo primo passo nel ruolo di
   giocatore..." introduce l'intero capitolo "Come giocare" (meccaniche +
   Personalità e Background), non solo la sotto-sezione "Come giocare". */
const RULES_CHAPTER_INTROS = {
  'Come giocare': 'Il tuo primo passo nel ruolo di giocatore è di immaginare e creare un personaggio tuo. Questo è una combinazione di statistiche di gioco, giochi di ruolo e la tua immaginazione. Per farlo sarà necessario creare un Background (consigliamo un file scritto per comodità con campi prestabiliti), questo documento di testo sarà utile al giocatore per scrivere un personaggio coerente con l’ambientazione del mondo di cui andrà a far parte e al Narratore per valutare il suo ruolo all’interno della narrativa. Sarà dunque necessario costruire un carattere che il giocatore riesca ad interpretare, con personalità, retroscena del suo passato, scopi e ideali. Una volta completato, il personaggio funge da base per la creazione della scheda, che dovrà necessariamente essere coerente con quanto descritto in fase di scrittura. Una cosa fondamentale è che, se si scrive di un personaggio combattente, bisogna conoscere almeno un minimo dello stile di combattimento utilizzato per comprenderne appieno limiti e pregi. La tua concezione del tuo personaggio potrebbe evolversi con ogni scelta che fai. L’importante è riunirsi portando “al tavolo” un personaggio che siete entusiasti di interpretare.'
};

/* Ricerca nel regolamento (Fase 4, piano D&D-Beyond-like): titolo e corpo
   di RULES_SECTIONS, confronto case/accent-insensitive (stessa normalizza-
   zione già usata altrove nel progetto per i nomi dei tratti,
   toLocaleLowerCase('it')). Tutto il regolamento è oggi incluso per
   chiunque (nessuna sezione riservata) — nessun filtro di accesso da
   applicare qui finché questo resterà vero. Ogni risultato porta l'indice
   di capitolo (RULES_CHAPTERS) necessario per aprirlo con
   openRulesChapter(). */
function searchRules(query) {
  const q = (query || '').trim().toLocaleLowerCase('it');
  if (!q) return [];
  const results = [];
  RULES_SECTIONS.forEach((s, sectionIndex) => {
    const title = s.t || '';
    const body = s.b || '';
    const titleMatch = title.toLocaleLowerCase('it').includes(q);
    const bodyLower = body.toLocaleLowerCase('it');
    const bodyIdx = bodyLower.indexOf(q);
    if (!titleMatch && bodyIdx < 0) return;
    const chapterIndex = RULES_CHAPTERS.findIndex(c => c.sections.includes(sectionIndex));
    if (chapterIndex < 0) return;
    let snippet = '';
    if (bodyIdx >= 0) {
      const start = Math.max(0, bodyIdx - 40);
      const end = Math.min(body.length, bodyIdx + q.length + 60);
      snippet = (start > 0 ? '…' : '') + body.slice(start, end).replace(/\s+/g, ' ') + (end < body.length ? '…' : '');
    }
    results.push({ type: 'rule', chapterIndex, chapterTitle: RULES_CHAPTERS[chapterIndex].t, sectionTitle: title, snippet, titleMatch });
  });
  // Rilevanza: una sezione il cui titolo corrisponde alla ricerca precede
  // le sezioni che la contengono solo nel corpo del testo (altrimenti una
  // menzione incidentale in una sezione precedente oscura il risultato
  // principale, es. "Boost" come termine di gioco citato altrove prima
  // della sezione "Boost" stessa). Stabile: a parità di titleMatch resta
  // l'ordine originale (quello dei capitoli/sezioni).
  return results
    .map((r, i) => ({ r, i }))
    .sort((a, b) => (b.r.titleMatch - a.r.titleMatch) || (a.i - b.i))
    .map(({ r }) => { delete r.titleMatch; return r; });
}

/* Segnalibri (Fase 4, piano D&D-Beyond-like): cache locale, riempita da
   refreshRuleBookmarks() (async, listMyBookmarkedSections() vive in
   js/cloud-account.js, caricato dopo) — la sezione bookmarkata è la
   CHIAVE STABILE (titolo), mai un indice numerico che potrebbe scivolare
   se RULES_SECTIONS viene riordinato. Vuota finché il fetch non risponde:
   nessun segnalibro mostrato come attivo per errore nel frattempo. */
let ruleBookmarks = new Set();
async function refreshRuleBookmarks() {
  if (typeof listMyBookmarkedSections !== 'function') return;
  try {
    const titles = await listMyBookmarkedSections();
    ruleBookmarks = new Set(titles || []);
  } catch (e) {
    return; // rete assente: la cache resta quella precedente, mai svuotata per un errore
  }
  // Ri-renderizza solo se l'utente è ancora sulla vista Regole (indice o
  // capitolo aperto): un fetch tornato tardi non deve alterare una vista
  // diversa nel frattempo aperta.
  if (!$('#view-rules').classList.contains('hidden')) {
    if ($('#rules-popup').classList.contains('hidden')) renderRulesIndex();
    else if (typeof currentRulesChapterIndex === 'number') openRulesChapter(currentRulesChapterIndex, true);
  }
}

function renderRulesIndex() {
  const bookmarkedSections = RULES_SECTIONS.filter(s => ruleBookmarks.has(s.t));
  const bookmarksHtml = bookmarkedSections.length ? `
    <p class="helper-text" style="margin-top:0;">I tuoi segnalibri</p>
    ${bookmarkedSections.map(s => {
      const chapterIndex = RULES_CHAPTERS.findIndex(c => c.sections.includes(RULES_SECTIONS.indexOf(s)));
      return `<button type="button" class="rule-title rules-index-item" data-rules-chapter="${chapterIndex}" data-rules-bookmark-jump="${escapeHtml(s.t)}">🔖 ${escapeHtml(s.t)} <span class="arrow">›</span></button>`;
    }).join('')}
    <div class="cm-sep" style="margin:12px 4px;"></div>
  ` : '';
  // Card per capitolo (piano UX "confronto D&D Beyond", S10): copertina
  // reale se già caricata (RULES_CHAPTER_COVERS), un'icona segnaposto
  // altrimenti — mai un'immagine generica finta al suo posto. Il numero di
  // argomenti è quello REALE (chapter.sections.length), non un testo
  // descrittivo inventato: il contenuto editoriale delle regole resta
  // fuori da questa modifica (solo struttura/visual, vedi commento CSS
  // corrispondente in css/style.css).
  const chapterCardsHtml = RULES_CHAPTERS.map((c, i) => {
    const cover = RULES_CHAPTER_COVERS[c.t];
    const coverHtml = cover
      ? `<div class="rcc-cover" style="background-image:url('${cover}')"></div>`
      : `<div class="rcc-cover"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4.5A2.5 2.5 0 016.5 2H20v17H6.5A2.5 2.5 0 004 21.5v-17z"/><path d="M4 19.5A2.5 2.5 0 016.5 17H20"/></svg></div>`;
    const count = c.sections.length;
    return `<button type="button" class="rules-chapter-card" data-rules-chapter="${i}">
      ${coverHtml}
      <div class="rcc-body">
        <div class="rcc-title">${escapeHtml(c.t)}</div>
        <div class="rcc-meta">${count} argoment${count === 1 ? 'o' : 'i'}</div>
      </div>
    </button>`;
  }).join('');
  $('#rules-body').innerHTML =
    bookmarksHtml +
    `<p class="helper-text">Il Manuale di Gioco e le guide pratiche, divisi per capitoli — tocca un capitolo per aprirlo.</p>` +
    `<div class="rules-chapter-grid">${chapterCardsHtml}</div>`;
}

/* Punto d'ingresso invariato per chi già chiama renderRules() (nav in
   copertina e menù a tendina): mostra sempre l'indice dei capitoli — i
   capitoli si aprono nel pop-up #rules-popup, sopra questa vista. Il
   fetch dei segnalibri parte qui, non blocca il rendering sincrono. */
function renderRules() {
  renderRulesIndex();
  refreshRuleBookmarks();
}

/* Indice del capitolo correntemente aperto nel pop-up (Fase 4): serve a
   refreshRuleBookmarks() per ridisegnare la stessa vista dopo il fetch,
   mai per navigare da sola. null quando il pop-up è chiuso. */
let currentRulesChapterIndex = null;

/* skipBookmarkRefresh: true solo quando chiamata DA refreshRuleBookmarks()
   stessa (che ha già i dati aggiornati) — evita un secondo fetch inutile
   ad ogni ri-render dopo il primo. */
function openRulesChapter(i, skipBookmarkRefresh) {
  const chapter = RULES_CHAPTERS[i];
  if (!chapter) return;
  currentRulesChapterIndex = i;
  $('#rules-popup-title').textContent = chapter.t;
  const chapterCover = RULES_CHAPTER_COVERS[chapter.t];
  const chapterCoverHtml = chapterCover ? `<img class="rule-cover rule-cover-chapter" src="${chapterCover}" alt="${escapeHtml(chapter.t)}">` : '';
  const chapterIntro = RULES_CHAPTER_INTROS[chapter.t];
  const chapterIntroHtml = chapterIntro ? `<p class="rule-text rule-intro">${escapeHtml(chapterIntro)}</p>` : '';
  $('#rules-popup-body').innerHTML = chapterCoverHtml + chapterIntroHtml + chapter.sections.map((si, idx) => {
    const s = RULES_SECTIONS[si];
    const cover = RULES_SECTION_COVERS[s.t];
    // Niente titolo doppio: se un'immagine (propria o quella del capitolo,
    // per la prima sotto-sezione) mostra già il nome scritto sopra il
    // testo, il .section-title qui sotto lo ripeterebbe inutilmente.
    const titleAlreadyShown = !!cover || (idx === 0 && !!chapterCover);
    const bookmarked = ruleBookmarks.has(s.t);
    const bookmarkBtn = `<button type="button" class="rule-bookmark-btn" data-rules-bookmark="${escapeHtml(s.t)}" aria-pressed="${bookmarked}" aria-label="${bookmarked ? 'Rimuovi dai segnalibri' : 'Aggiungi ai segnalibri'}: ${escapeHtml(s.t)}">${bookmarked ? '🔖' : '📑'}</button>`;
    return `
      <div data-rule-section="${escapeHtml(s.t)}">
      ${cover ? `<img class="rule-cover" src="${cover}" alt="${escapeHtml(s.t)}">` : ''}
      <div class="row-between" style="margin-top:14px;align-items:center;">
        ${titleAlreadyShown ? '<span></span>' : `<div class="section-title" style="margin-top:0;"><span class="dot neutral"></span>${escapeHtml(s.t)}</div>`}
        ${bookmarkBtn}
      </div>
      <div class="box"><div class="box-bar"></div><div class="box-pad rule-text">${formatRuleBody(s.b)}</div></div>
      </div>
    `;
  }).join('');
  $('#rules-popup').classList.remove('hidden');
  if (!skipBookmarkRefresh) refreshRuleBookmarks();
}
/* Collegamento contestuale (FC1, macrofase completamento funzionale):
   apre il capitolo che contiene una sezione specifica (per titolo, mai un
   indice numerico fragile) e ci scorre sopra — usato dai link "vedi FAQ",
   "vedi Glossario" ecc. sparsi nelle altre schermate dell'app, così non
   aprono mai l'intero blocco "Guide" lasciando l'utente a cercare a mano. */
function openRuleSection(sectionTitle) {
  const sectionIndex = RULES_SECTIONS.findIndex(s => s.t === sectionTitle);
  if (sectionIndex < 0) return;
  const chapterIndex = RULES_CHAPTERS.findIndex(c => c.sections.includes(sectionIndex));
  if (chapterIndex < 0) return;
  showView('rules');
  openRulesChapter(chapterIndex);
  requestAnimationFrame(() => {
    const el = document.querySelector(`[data-rule-section="${CSS.escape(sectionTitle)}"]`);
    if (el) el.scrollIntoView({ block: 'start' });
  });
}
/* Il testo delle regole è dati statici (non input utente): **parola**
   diventa grassetto per i nomi di statistiche/caratteristiche, come nel
   resto del manuale (es. Q.I., P.R., Carisma...). Sempre passato prima da
   escapeHtml, la sostituzione avviene sull'HTML già sicuro. */
function formatRuleBody(text) {
  return escapeHtml(text).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
}
function closeRulesChapter() {
  $('#rules-popup').classList.add('hidden');
  currentRulesChapterIndex = null;
}

/* Toggle segnalibro (Fase 4): optimistic update sul bottone cliccato
   (stesso pattern già in uso per "listed"/"premise published" nelle
   campagne, js/cloud-account.js) — la cache locale ruleBookmarks cambia
   subito, la scrittura reale è async; un fallimento la annulla e avvisa. */
async function toggleRuleBookmark(sectionTitle, btn) {
  const wasBookmarked = ruleBookmarks.has(sectionTitle);
  if (typeof addRuleBookmark !== 'function' || typeof removeRuleBookmark !== 'function') return;
  btn.disabled = true;
  try {
    if (wasBookmarked) { await removeRuleBookmark(sectionTitle); ruleBookmarks.delete(sectionTitle); }
    else { await addRuleBookmark(sectionTitle); ruleBookmarks.add(sectionTitle); }
    const nowBookmarked = !wasBookmarked;
    btn.textContent = nowBookmarked ? '🔖' : '📑';
    btn.setAttribute('aria-pressed', String(nowBookmarked));
    btn.setAttribute('aria-label', `${nowBookmarked ? 'Rimuovi dai segnalibri' : 'Aggiungi ai segnalibri'}: ${sectionTitle}`);
  } catch (e) {
    if (typeof toast === 'function') toast('Errore: ' + (typeof describeError === 'function' ? describeError(e) : e.message));
  } finally {
    btn.disabled = false;
  }
}

function wireRulesEvents() {
  $('#rules-body').addEventListener('click', e => {
    const item = e.target.closest('[data-rules-chapter]');
    if (item) openRulesChapter(Number(item.dataset.rulesChapter));
  });
  $('#rules-popup-close').addEventListener('click', closeRulesChapter);
  $('#rules-popup-body').addEventListener('click', e => {
    const btn = e.target.closest('[data-rules-bookmark]');
    if (btn) toggleRuleBookmark(btn.dataset.rulesBookmark, btn);
  });
}
